package web

import "html/template"

var continuityTemplate = template.Must(template.New("continuity").Parse(`<!doctype html>
<html lang="en">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CRAB continuity</title><link rel="stylesheet" href="/static/app.css"></head>
<body>
<header class="shell"><div><p class="eyebrow">Cyber Response Action Board</p><h1>CRAB</h1></div><div class="version">{{.Version}}</div></header>
<main>
{{if .Error}}<section class="notice notice--error" role="alert"><strong>Refused</strong><p>{{.Error}}</p></section>{{end}}
{{if .Intake}}
<nav class="crumb"><a href="/">Incidents</a><span>/</span><strong>First-report intake</strong></nav>
<div class="toolbar"><div><p class="kicker">Intake</p><h2>First reports</h2><p>Fast capture before an incident exists. Phone camera and file evidence stay inside the hostile-byte boundary.</p></div><div><strong>{{.Intake.HumanID}}</strong><br><small>{{.Intake.Role}}</small></div></div>
<section class="dashboard-grid">
<article><h3>Capture first report</h3><form method="post" action="/intake" enctype="multipart/form-data" class="form-grid">
<label>Reporter<input name="reporter" autocomplete="name"></label>
<label>Contact route<input name="contact_route" placeholder="Phone, email or callback route"></label>
<label>Received at<input type="datetime-local" name="received_at"><small>Leave blank to use capture time.</small></label>
<label>Time confidence<select name="time_confidence"><option value="trusted">Trusted</option><option value="drifting">Drifting</option><option value="untrusted">Untrusted</option></select></label>
<label>Description<textarea name="description" required></textarea></label>
<label>Affected assets/services<input name="affected"></label>
<label>Immediate impact<textarea name="immediate_impact"></textarea></label>
<label>Source channel<select name="source_channel" required><option value="phone">Phone</option><option value="email">Email</option><option value="monitoring">Monitoring</option><option value="chat">Chat</option><option value="in_person">In person</option><option value="other">Other</option></select></label>
<label>Camera photo<input type="file" name="camera" accept="image/*" capture="environment"></label>
<label>Other evidence<input type="file" name="attachment" multiple></label>
<button>Record first report</button></form></article>
<article><h3>Intake rule</h3><p>Capture what is known. Do not force an incident declaration before there is enough information.</p><p>Association, retention or rejection is recorded separately so the original report remains immutable.</p></article>
</section>
<section class="panel"><h3>Report queue</h3>{{range .Intake.Reports}}<div class="approval"><strong>{{.Description}}</strong><small>{{.ReportID}} · {{.SourceChannel}} · received {{.ReceivedAt}} · {{.AttachmentCount}} attachment(s)</small>{{if .Reporter}}<p>Reporter: {{.Reporter}}{{if .ContactRoute}} · {{.ContactRoute}}{{end}}</p>{{end}}{{if .Affected}}<p>Affected: {{.Affected}}</p>{{end}}{{if .ImmediateImpact}}<p>Impact: {{.ImmediateImpact}}</p>{{end}}{{if .Decision}}<p><strong>Disposition:</strong> {{.Decision}}{{if .IncidentID}} · {{.IncidentID}}{{end}} — {{.Reason}}</p>{{else if $.Intake.CanTriage}}<form method="post" action="/intake/{{.ReportID}}/triage" class="form-grid"><label>Disposition<select name="decision"><option value="associate">Associate to incident</option><option value="retain">Retain for review</option><option value="reject">Reject as non-incident</option></select></label><label>Incident ID<input name="incident_id" placeholder="Required when associating"></label><label>Reason<textarea name="reason" required></textarea></label><button>Record disposition</button></form>{{else}}<p class="muted">Major triage required.</p>{{end}}</div>{{else}}<p class="muted">No first reports captured.</p>{{end}}</section>
{{else if .Incident}}
<nav class="crumb"><a href="/">Incidents</a><span>/</span><a href="/incident/{{.Incident.IncidentID}}">{{.Incident.IncidentID}}</a><span>/</span><strong>Operations</strong></nav>
<section class="incident-head"><div><p class="kicker">{{.Incident.Mode}} · operational continuity</p><h2>{{.Incident.Title}}</h2><p>{{.Incident.Summary}}</p></div><div class="severity"><span>Current severity</span><strong>{{.Incident.Severity}}</strong></div></section>
<section class="dashboard-grid">
<article><h3>Scope &amp; impact</h3>{{range .Operations.Scopes}}<div class="approval"><strong>{{.Impact}}</strong><small>{{.Confidence}} · {{.Maker}} · {{.RecordedAt}}</small>{{if .AffectedAssets}}<p>Assets: {{.AffectedAssets}}</p>{{end}}{{if .AffectedServices}}<p>Services: {{.AffectedServices}}</p>{{end}}{{if .PeopleDataPopulations}}<p>People/data: {{.PeopleDataPopulations}}</p>{{end}}{{if .Locations}}<p>Locations: {{.Locations}}</p>{{end}}{{if .Suppliers}}<p>Suppliers: {{.Suppliers}}</p>{{end}}<p>Reason/evidence: {{.ReasonEvidence}}</p></div>{{else}}<p class="muted">No scope assessment yet.</p>{{end}}<form method="post" action="/incident/{{.Incident.IncidentID}}/operations/scope" class="form-grid"><label>Impact<textarea name="impact" required></textarea></label><label>Confidence<input name="confidence" placeholder="high / medium / low" required></label><label>Reason / evidence<textarea name="reason_evidence" required></textarea></label><label>Affected assets<textarea name="affected_assets" placeholder="One per line"></textarea></label><label>Affected services<textarea name="affected_services" placeholder="One per line"></textarea></label><label>People / data populations<textarea name="people_data_populations" placeholder="One per line"></textarea></label><label>Locations<textarea name="locations" placeholder="One per line"></textarea></label><label>Suppliers<textarea name="suppliers" placeholder="One per line"></textarea></label><button>Record scope assessment</button></form></article>
<article><h3>Severity governance</h3>{{range .Operations.PendingSeverity}}<form method="post" action="/incident/{{$.Incident.IncidentID}}/operations/severity/decide" class="approval"><input type="hidden" name="record_id" value="{{.RecordID}}"><input type="hidden" name="version" value="{{.Version}}"><strong>Proposed: {{.Severity}}</strong><small>{{.Maker}} · {{.ProposedAt}}</small><p>{{.ReasonEvidence}}</p><div><button name="outcome" value="confirmed">Confirm</button><button class="secondary" name="outcome" value="rejected">Reject</button></div></form>{{else}}<p class="muted">No severity change awaiting confirmation.</p>{{end}}<form method="post" action="/incident/{{.Incident.IncidentID}}/operations/severity" class="form-grid"><label>Proposed severity<input name="severity" required></label><label>Reason / evidence<textarea name="reason_evidence" required></textarea></label><button>Propose severity change</button></form><h3>Confirmed history</h3>{{range .Operations.SeverityHistory}}<p><strong>{{.Severity}}</strong><br><small>{{.Maker}} → {{.Confirmer}} · {{.RecordedAt}}</small><br>{{.ReasonEvidence}}</p>{{else}}<p class="muted">No confirmed severity changes.</p>{{end}}</article>
<article><h3>Shift handover</h3>{{range .Operations.Handovers}}<div class="approval"><strong>{{.Situation}}</strong><small>{{.Maker}} · {{.RecordedAt}}</small>{{if .OperationalRoles}}<p>Roles: {{.OperationalRoles}}</p>{{end}}{{if .CriticalActions}}<p>Critical actions: {{.CriticalActions}}</p>{{end}}{{if .PendingDecisions}}<p>Pending decisions: {{.PendingDecisions}}</p>{{end}}{{if .Obligations}}<p>Obligations: {{.Obligations}}</p>{{end}}{{if .Unknowns}}<p>Unknowns: {{.Unknowns}}</p>{{end}}{{if .NextObjectives}}<p>Next objectives: {{.NextObjectives}}</p>{{end}}{{if .CommunicationCommitments}}<p>Communications: {{.CommunicationCommitments}}</p>{{end}}</div>{{else}}<p class="muted">No handover generated.</p>{{end}}<form method="post" action="/incident/{{.Incident.IncidentID}}/operations/handover" class="form-grid"><label>Next objectives<textarea name="next_objectives" placeholder="One per line"></textarea></label><label>Communication commitments<textarea name="communication_commitments" placeholder="One per line"></textarea></label><button>Generate handover from current board</button></form></article>
</section>
<section class="dashboard-grid">
<article><h3>Resource coordination</h3>{{range .Operations.Resources}}<div class="approval"><strong>{{.Request}}</strong><small>{{.Category}} · {{.Priority}} · {{.Status}}</small><p>Owner: {{.OwnerHumanID}} · authority: {{.AuthoritySource}}</p>{{if .Notes}}<p>{{.Notes}}</p>{{end}}<form method="post" action="/incident/{{$.Incident.IncidentID}}/operations/resource" class="form-grid"><input type="hidden" name="record_id" value="{{.RecordID}}"><input type="hidden" name="category" value="{{.Category}}"><input type="hidden" name="request" value="{{.Request}}"><label>Owner<input name="owner" value="{{.OwnerHumanID}}" required></label><label>Priority<input name="priority" value="{{.Priority}}" required></label><label>Status<input name="status" value="{{.Status}}" required></label><label>Authority source<input name="authority_source" value="{{.AuthoritySource}}" required></label><label>Notes<textarea name="notes">{{.Notes}}</textarea></label><button>Update request</button></form></div>{{else}}<p class="muted">No resource requests.</p>{{end}}<h3>New request</h3><form method="post" action="/incident/{{.Incident.IncidentID}}/operations/resource" class="form-grid"><label>Category<input name="category" required></label><label>Request<textarea name="request" required></textarea></label><label>Owner<input name="owner" required></label><label>Priority<input name="priority" value="P1" required></label><label>Status<input name="status" value="requested" required></label><label>Authority source<input name="authority_source" required></label><label>Notes<textarea name="notes"></textarea></label><button>Record resource request</button></form></article>
<article><h3>Known facts</h3>{{range .Incident.Facts}}<p><strong>{{.Statement}}</strong><br><small>{{.Source}}</small></p>{{else}}<p class="muted">No facts recorded.</p>{{end}}</article>
<article><h3>Live actions</h3>{{range .Incident.Actions}}<p><strong>{{.Title}}</strong><br><small>{{.Owner}} · {{.Status}} · {{.Priority}}</small></p>{{else}}<p class="muted">No confirmed actions.</p>{{end}}<p><a href="/incident/{{.Incident.IncidentID}}">Open decision/timeline board</a></p></article>
</section>
{{end}}
</main></body></html>`))
